function esAnswerText(v){return String(v).replace(/[0-9#*]\uFE0F?\u20E3/g," ").replace(/[\u{1F000}-\u{1FAFF}\u2600-\u27BF\u{1F1E6}-\u{1F1FF}]/gu," ").replace(/[\u200D\uFE0E\uFE0F]/g,"").normalize("NFKC")}
