var norm0=function(x){return esAnswerText(x).normalize("NFKC").replace(/[’‘]/g,"'").trim().toLowerCase().replace(/\s+/g," ").replace(/\s+([.!?,])/g,"$1").replace(/[.!?،]+$/,"")};
var norm=function(x){return norm0(esContr(x))};
var match=function(a,b,q){var clean=function(x){return String(x).normalize("NFKC").replace(/[’‘]/g,"'").trim().replace(/\s+/g," ").replace(/\s+([.!?,])/g,"$1")};if(q.strict_punctuation||q.strict_case){a=clean(a);b=clean(b);return (q.strict_case?a:a.toLowerCase())===(q.strict_case?b:b.toLowerCase())}return norm(a)===norm(b)};
var join=function(xs,letters){return letters?xs.join(""):xs.join(" ").replace(/\s+([.!?,])/g,"$1")};
function optionOrder(q){var seed=2166136261;for(var i=0;i<q.id.length;i++)seed=Math.imul(seed^q.id.charCodeAt(i),16777619)>>>0;var xs=q.options.slice();for(var k=xs.length-1;k>0;k--){seed=Math.imul(seed,1664525)+1013904223>>>0;var j=seed%(k+1);var t=xs[k];xs[k]=xs[j];xs[j]=t}return xs}
