      var line=document.createElement('span');line.className='ds-fb-t sa-fbline';var lspan=document.createElement('span');lspan.textContent=r.ok?'أحسنت':s('no');if(r.ok&&DS.lang()==='en')lspan.className='sr-only';line.appendChild(lspan);if(r.ok){var gem=document.createElement('span');gem.className='sr-only';gem.textContent='\u2705';line.appendChild(gem);line.appendChild(document.createTextNode(' '));var lspan2=document.createElement('span');lspan2.textContent=DS.t('إجابة صحيحة','Correct answer');line.appendChild(lspan2);var lspan3=document.createElement('span');lspan3.className='sr-only';lspan3.textContent=s('ok');line.appendChild(lspan3)}fb.appendChild(line);
